        --them:#fff; --good:#15803d; --bad:#b91c1c; --warn:#a16207; --accent:#1d4ed8; }
* { box-sizing:border-box }
body { margin:0; font:14px/1.45 -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif; color:var(--ink);
       background:var(--bg); display:grid; grid-template-columns:330px 1fr; height:100vh }
nav { border-right:1px solid var(--line); overflow:auto; background:var(--panel) }
nav input { width:calc(100% - 20px); margin:10px; padding:7px 9px; border:1px solid var(--line); border-radius:6px }
.item { padding:9px 12px; border-top:1px solid var(--line); cursor:pointer }
.item:hover { background:#f5f5f4 } .item.on { background:#e0e7ff }
.item b { font-weight:600 } .item small { color:var(--mute); display:block }
.score { float:right; font-variant-numeric:tabular-nums; font-weight:600 }
main { overflow:auto; padding:22px 28px 60px }
h1 { font-size:19px; margin:0 0 4px } .sub { color:var(--mute); margin-bottom:16px }
.kpis { display:flex; gap:10px; flex-wrap:wrap; margin-bottom:12px }
.kpi { background:var(--panel); border:1px solid var(--line); border-radius:8px; padding:8px 12px; min-width:120px }
.kpi span { color:var(--mute); font-size:12px; display:block } .kpi b { font-size:16px; font-variant-numeric:tabular-nums }
.bd { color:var(--mute); font-size:12px; margin-bottom:18px }
h2 { font-size:15px; margin:26px 0 10px; padding-top:10px; border-top:2px solid var(--line) }
